export default JSON.parse("{\"workId\":\"han-fei-zi\",\"chapter\":{\"id\":\"han-fei-zi_ch-14\",\"workId\":\"han-fei-zi\",\"order\":14,\"title\":\"奸劫弒臣\",\"difficulty\":4,\"estimatedMinutes\":13,\"passageIds\":[\"han-fei-zi_ch-14_p-1\",\"han-fei-zi_ch-14_p-2\",\"han-fei-zi_ch-14_p-3\",\"han-fei-zi_ch-14_p-4\",\"han-fei-zi_ch-14_p-5\",\"han-fei-zi_ch-14_p-6\"],\"tags\":[\"法家\",\"帝王術\",\"法術勢\"]},\"passages\":[{\"id\":\"han-fei-zi_ch-14_p-1\",\"chapterId\":\"han-fei-zi_ch-14\",\"order\":1,\"canonicalText\":\"凡姦臣皆欲順人主之心以取親幸之勢者也。是以主有所善，臣從而譽之；主有所憎，臣因而毀之。凡人之大體，取捨同者則相是也，取捨異者則相非也。今人臣之所譽者，人主之所是也，此之謂同取。人臣之所毀者，人主之所非也，此之謂同舍。夫取捨合而相與逆者，未嘗聞也，此人臣之所以取信幸之道也。夫姦臣得乘信幸之勢以毀譽進退群臣者，人主非有術數以御之也，非參驗以審之也，必將以曩之合己信今之言，此倖臣之所以得欺主成私者也。故主必欺於上，而臣必重於下矣，此之謂擅主之臣。國有擅主之臣，則羣下不得盡其智力以陳其忠，百官之吏不得奉法以致其功矣。何以明之？夫安利者就之，危害者去之，此人之情也。今為臣盡力以致功，竭智以陳忠者，其身困而家貧，父子罹其害；為姦利以弊人主，行財貨以事貴重之臣者，身尊家富，父子被其澤；人焉能去安利之道而就危害之處哉？治國若此其過也，而上欲下之無姦，吏之奉法，其不可得亦明矣。故左右知貞信之不可以得安利也，必曰：「我以忠信事上積功勞而求安，是猶盲而欲知黑白之情，必不幾矣。若以道化行正理不趨富貴事上而求安，是猶聾而欲審清濁之聲也，愈不幾矣。二者不可以得安，我安能無相比周、蔽主上、為姦私以適重人哉？」此必不顧人主之義矣。其百官之吏，亦知方正之不可以得安也，必曰：「我以清廉事上而求安，若無規矩而欲為方圓也，必不幾矣。若以守法不朋黨治官而求安，是猶以足搔頂也，愈不幾也。二者不可以得安，能無廢法行私以適重人哉？」此必不顧君上之法矣。故以私為重人者眾，而以法事君者少矣。是以主孤於上而臣成黨於下，此田成之所以弒簡公者也。\",\"sentenceIds\":[\"han-fei-zi_ch-14_p-1_s-1\",\"han-fei-zi_ch-14_p-1_s-2\",\"han-fei-zi_ch-14_p-1_s-3\",\"han-fei-zi_ch-14_p-1_s-4\",\"han-fei-zi_ch-14_p-1_s-5\",\"han-fei-zi_ch-14_p-1_s-6\",\"han-fei-zi_ch-14_p-1_s-7\",\"han-fei-zi_ch-14_p-1_s-8\",\"han-fei-zi_ch-14_p-1_s-9\",\"han-fei-zi_ch-14_p-1_s-10\",\"han-fei-zi_ch-14_p-1_s-11\",\"han-fei-zi_ch-14_p-1_s-12\",\"han-fei-zi_ch-14_p-1_s-13\",\"han-fei-zi_ch-14_p-1_s-14\",\"han-fei-zi_ch-14_p-1_s-15\",\"han-fei-zi_ch-14_p-1_s-16\",\"han-fei-zi_ch-14_p-1_s-17\",\"han-fei-zi_ch-14_p-1_s-18\",\"han-fei-zi_ch-14_p-1_s-19\",\"han-fei-zi_ch-14_p-1_s-20\",\"han-fei-zi_ch-14_p-1_s-21\",\"han-fei-zi_ch-14_p-1_s-22\",\"han-fei-zi_ch-14_p-1_s-23\",\"han-fei-zi_ch-14_p-1_s-24\",\"han-fei-zi_ch-14_p-1_s-25\",\"han-fei-zi_ch-14_p-1_s-26\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡姦臣下僚屬皆欲順人主的心以取親幸的至高權力威勢的人或事物啊。是以主有所善，臣下僚屬從而且譽的；主有所憎，臣下僚屬因而且毀的。凡人的大體，取捨同的人或事物則相是啊，取捨異的人或事物則相絕不是啊。今人臣下僚屬的所譽的人或事物，人主的所是啊，此的謂同取。人臣下僚屬的所毀的人或事物，人主的所絕不是啊，此的謂同舍。夫取捨合而且相與逆的人或事物，未嘗聞啊，此人臣下僚屬的所以取信幸的道啊。夫姦臣下僚屬得乘信幸的至高權力威勢以毀譽進退群臣下僚屬的人或事物，人主絕不是有御臣心術權謀數以御的啊，絕不是參驗以審的啊，必將以曩的合己信今的言，此倖臣下僚屬的所以得欺主成私的人或事物啊。所以主必欺於上，而且臣下僚屬必重於下矣，此的謂擅主的臣下僚屬。國有擅主的臣下僚屬，則羣下不得盡他的智力以陳他的忠，百官的吏不得奉國家法度法規以致他的功矣。何以明的？夫安利的人或事物就的，危害的人或事物去的，此人的情啊。今為臣下僚屬盡力以致功，竭智以陳忠的人或事物，他的身困而且家貧，父子罹他的害；為姦利以弊人主，行財貨以事貴重的臣下僚屬的人或事物，身尊家富，父子被他的澤；人焉能去安利的道而且就危害的處哉？治國若此他的過啊，而且上欲下的無姦，吏的奉國家法度法規，他的不可得亦明矣。所以左右知貞信的不可以得安利啊，必說道：我以忠信事上積功勞而且求安，是猶盲而且欲知黑白的情，必不幾矣。若以道化行正理不趨富貴事上而且求安，是猶聾而且欲審清濁的聲啊，愈不幾矣。二的人或事物不可以得安，我安能無相比周、蔽主上、為姦私以適重人哉？此必不顧人主的義矣。他的百官的吏，亦知方正的不可以得安啊，必說道：我以清廉事上而且求安，若無規矩而且欲為方圓啊，必不幾矣。若以守國家法度法規不朋黨治官而且求安，是猶以足搔頂啊，愈不幾啊。二的人或事物不可以得安，能無廢國家法度法規行私以適重人哉？此必不顧君主統治者上的國家法度法規矣。所以以私為重人的人或事物眾，而且以國家法度法規事君主統治者的人或事物少矣。是以主孤於上而且臣下僚屬成黨於下，此田成的所以弒簡公的人或事物啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈奸劫弒臣〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「凡姦臣皆欲順人主之心以取親幸之勢者也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「凡姦臣皆欲順人主之心以取親幸之勢者也。是以主有所善，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-14_p-2\",\"chapterId\":\"han-fei-zi_ch-14\",\"order\":2,\"canonicalText\":\"夫有術者之為人臣也，得效度數之言，上明主法，下困姦臣，以尊主安國者也。是以度數之言得效於前，則賞罰必用於後矣。人主誠明於聖人之術，而不苟於世俗之言，循名實而定是非，因參驗而審言辭。是以左右近習之臣，知偽詐之不可以得安也，必曰：「我不去姦私之行盡力竭智以事主，而乃以相與比周妄毀譽以求安，是猶負千鈞之重，陷於不測之淵而求生也，必不幾矣。」百官之吏，亦知為姦利之不可以得安也，必曰：「我不以清廉方正奉法，乃以貪污之心枉法以取私利，是猶上高陵之顛，墮峻谿之下而求生，必不幾矣。」安危之道若此其明也，左右安能以虛言惑主，而百官安敢以貪漁下？是以臣得陳其忠而不弊，下得守其職而不怨。此管仲之所以治齊，而商君之所以強秦也。從是觀之，則聖人之治國也，固有使人不得不愛我之道，而不恃人之以愛為我也。恃人之以愛為我者危矣，恃吾不可不為者安矣。夫君臣非有骨肉之親，正直之道可以得利，則臣盡力以事主；正直之道不可以得安，則臣行私以幹上。明主知之，故設利害之道以示天下而已矣。夫是以人主雖不口教百官，不目索姦邪，而國已治矣。人主者，非目若離婁乃為明也，非耳若師曠乃為聰也。目必，不任其數，而待目以為明，所見者少矣，非不弊之術也。耳必，不因其勢，而待耳以為聰，所聞者寡矣，非不欺之道也。明主者，使天下不得不為己視，天下不得不為己聽。故身在深宮之中而明照四海之內，而天下弗能蔽、弗能欺者何也？闇亂之道廢，而聰明之勢興也。故善任勢者國安，不知因其勢者國危。古秦之俗，君臣廢法而服私，是以國亂兵弱而主卑。商君說秦孝公以變法易俗而明公道，賞告姦，困末作而利本事。當此之時，秦民習故俗之有罪可以得免、無功可以得尊顯也，故輕犯新法。於是犯之者其誅重而必，告之者其賞厚而信，故姦莫不得而被刑者眾，民疾怨而眾過日聞。孝公不聽，遂行商君之法，民後知有罪之必誅，而私姦者眾也，故民莫犯，其刑無所加。是以國治而兵強，地廣而主尊。此其所以然者，匿罪之罰重，而告姦之賞厚也。此亦使天下必為己視聽之道也。至治之法術已明矣，而世學者弗知也。\",\"sentenceIds\":[\"han-fei-zi_ch-14_p-2_s-1\",\"han-fei-zi_ch-14_p-2_s-2\",\"han-fei-zi_ch-14_p-2_s-3\",\"han-fei-zi_ch-14_p-2_s-4\",\"han-fei-zi_ch-14_p-2_s-5\",\"han-fei-zi_ch-14_p-2_s-6\",\"han-fei-zi_ch-14_p-2_s-7\",\"han-fei-zi_ch-14_p-2_s-8\",\"han-fei-zi_ch-14_p-2_s-9\",\"han-fei-zi_ch-14_p-2_s-10\",\"han-fei-zi_ch-14_p-2_s-11\",\"han-fei-zi_ch-14_p-2_s-12\",\"han-fei-zi_ch-14_p-2_s-13\",\"han-fei-zi_ch-14_p-2_s-14\",\"han-fei-zi_ch-14_p-2_s-15\",\"han-fei-zi_ch-14_p-2_s-16\",\"han-fei-zi_ch-14_p-2_s-17\",\"han-fei-zi_ch-14_p-2_s-18\",\"han-fei-zi_ch-14_p-2_s-19\",\"han-fei-zi_ch-14_p-2_s-20\",\"han-fei-zi_ch-14_p-2_s-21\",\"han-fei-zi_ch-14_p-2_s-22\",\"han-fei-zi_ch-14_p-2_s-23\",\"han-fei-zi_ch-14_p-2_s-24\",\"han-fei-zi_ch-14_p-2_s-25\",\"han-fei-zi_ch-14_p-2_s-26\",\"han-fei-zi_ch-14_p-2_s-27\",\"han-fei-zi_ch-14_p-2_s-28\",\"han-fei-zi_ch-14_p-2_s-29\",\"han-fei-zi_ch-14_p-2_s-30\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夫有御臣心術權謀的人或事物的為人臣下僚屬啊，得效度數的言，上明主國家法度法規，下困姦臣下僚屬，以尊主安國的人或事物啊。是以度數的言得效於前，則賞賜恩惠刑罰制裁必用於後矣。人主誠明於聖人的御臣心術權謀，而且不苟於世俗的言，循名實而且定是絕不是，因參驗而且審言辭。是以左右近習的臣下僚屬，知偽詐的不可以得安啊，必說道：我不去姦私的行盡力竭智以事主，而且乃以相與比周妄毀譽以求安，是猶負千鈞的重，陷於不測的淵而且求生啊，必不幾矣。百官的吏，亦知為姦利的不可以得安啊，必說道：我不以清廉方正奉國家法度法規，乃以貪污的心枉國家法度法規以取私利，是猶上高陵的顛，墮峻谿的下而且求生，必不幾矣。安危的道若此他的明啊，左右安能以虛言惑主，而且百官安敢以貪漁下？是以臣下僚屬得陳他的忠而且不弊，下得守他的職而且不怨。此管仲的所以治齊，而且商君主統治者的所以強秦啊。從是觀的，則聖人的治國啊，固有使人不得不愛我的道，而且不恃人的以愛為我啊。恃人的以愛為我的人或事物危矣，恃吾不可不為的人或事物安矣。夫君主統治者臣下僚屬絕不是有骨肉的親，正直的道可以得利，則臣下僚屬盡力以事主；正直的道不可以得安，則臣下僚屬行私以幹上。明主知的，所以設利害的道以示天下而且已矣。夫是以人主雖不口教百官，不目索姦邪，而且國已治矣。人主的人或事物，絕不是目若離婁乃為明啊，絕不是耳若師曠乃為聰啊。目必，不任他的數，而且待目以為明，所見的人或事物少矣，絕不是不弊的御臣心術權謀啊。耳必，不因他的至高權力威勢，而且待耳以為聰，所聞的人或事物寡矣，絕不是不欺的道啊。明主的人或事物，使天下不得不為己視，天下不得不為己聽。所以身在深宮的中而且明照四海的內，而且天下弗能蔽、弗能欺的人或事物何啊？闇亂的道廢，而且聰明的至高權力威勢興啊。所以善任至高權力威勢的人或事物國安，不知因他的至高權力威勢的人或事物國危。古秦的俗，君主統治者臣下僚屬廢國家法度法規而且服私，是以國亂兵弱而且主卑。商君主統治者說秦孝公以變國家法度法規易俗而且明公道，賞賜恩惠告姦，困末作而且利本事。當此的時，秦民習所以俗的有罪可以得免、無功可以得尊顯啊，所以輕犯新國家法度法規。於是犯的的人或事物他的誅重而且必，告的的人或事物他的賞賜恩惠厚而且信，所以姦莫不得而且被刑的人或事物眾，民疾怨而且眾過日聞。孝公不聽，遂行商君主統治者的國家法度法規，民後知有罪的必誅，而且私姦的人或事物眾啊，所以民莫犯，他的刑無所加。是以國治而且兵強，地廣而且主尊。此他的所以然的人或事物，匿罪的刑罰制裁重，而且告姦的賞賜恩惠厚啊。此亦使天下必為己視聽的道啊。至治的國家法度法規御臣心術權謀已明矣，而且世學的人或事物弗知啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈奸劫弒臣〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「夫有術者之為人臣也，得效度數之言，上明主法，下困姦臣，以尊主安國者也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「夫有術者之為人臣也，得效度數之言，上明主法，下困姦臣……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-14_p-3\",\"chapterId\":\"han-fei-zi_ch-14\",\"order\":3,\"canonicalText\":\"且夫世之愚學，皆不知治亂之情，讘䛟多誦先古之書，以亂當世之治；智慮不足以避阱井之陷，又妄非有術之士。聽其言者危，用其計者亂，此亦愚之至大，而患之至甚者也。俱與有術之士，有談說之名，而實相去千萬也，此夫名同而實有異者也。夫世愚學之人比有術之士也，猶螘垤之比大陵也，其相去遠矣。而聖人者，審於是非之實，察於治亂之情也。故其治國也，正明法，陳嚴刑，將以救羣生之亂，去天下之禍，使強不陵弱，眾不暴寡，耆老得遂，幼孤得長，邊境不侵，君臣相親，父子相保，而無死亡係虜之患，此亦功之至厚者也。愚人不知，顧以為暴。愚者固欲治而惡其所以治，皆惡危而喜其所以危者。何以知之？夫嚴刑重罰者，民之所惡也，而國之所以治也；哀憐百姓、輕刑罰者，民之所喜，而國之所以危也。聖人為法國者，必逆於世，而順於道德。知之者，同於義而異於俗；弗知之者，異於義而同於俗。天下知之者少，則義非矣。\",\"sentenceIds\":[\"han-fei-zi_ch-14_p-3_s-1\",\"han-fei-zi_ch-14_p-3_s-2\",\"han-fei-zi_ch-14_p-3_s-3\",\"han-fei-zi_ch-14_p-3_s-4\",\"han-fei-zi_ch-14_p-3_s-5\",\"han-fei-zi_ch-14_p-3_s-6\",\"han-fei-zi_ch-14_p-3_s-7\",\"han-fei-zi_ch-14_p-3_s-8\",\"han-fei-zi_ch-14_p-3_s-9\",\"han-fei-zi_ch-14_p-3_s-10\",\"han-fei-zi_ch-14_p-3_s-11\",\"han-fei-zi_ch-14_p-3_s-12\",\"han-fei-zi_ch-14_p-3_s-13\",\"han-fei-zi_ch-14_p-3_s-14\",\"han-fei-zi_ch-14_p-3_s-15\",\"han-fei-zi_ch-14_p-3_s-16\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"再的人或事物況且世的愚學，皆不知治亂的情，讘䛟多誦先古的書，以亂當世的治；智慮不足以避阱井的陷，又妄絕不是有御臣心術權謀的士。聽他的言的人或事物危，用他的計的人或事物亂，此亦愚的至大，而且患的至甚的人或事物啊。俱與有御臣心術權謀的士，有談說的名，而且實相去千萬啊，此夫名同而且實有異的人或事物啊。夫世愚學的人比有御臣心術權謀的士啊，猶螘垤的比大陵啊，他的相去遠矣。而且聖人的人或事物，審於是絕不是的實，察於治亂的情啊。所以他的治國啊，正明國家法度法規，陳嚴刑，將以救羣生的亂，去天下的禍，使強不陵弱，眾不暴寡，耆老得遂，幼孤得長，邊境不侵，君主統治者臣下僚屬相親，父子相保，而且無死亡係虜的患，此亦功的至厚的人或事物啊。愚人不知，顧以為暴。愚的人或事物固欲治而且惡他的所以治，皆惡危而且喜他的所以危的人或事物。何以知的？夫嚴刑重刑罰制裁的人或事物，民的所惡啊，而且國的所以治啊；哀憐百姓、輕刑刑罰制裁的人或事物，民的所喜，而且國的所以危啊。聖人為國家法度法規國的人或事物，必逆於世，而且順於道德。知的的人或事物，同於義而且異於俗；弗知的的人或事物，異於義而且同於俗。天下知的的人或事物少，則義絕不是矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈奸劫弒臣〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「且夫世之愚學，皆不知治亂之情，讘䛟多誦先古之書，以亂當世之治」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「且夫世之愚學，皆不知治亂之情，讘䛟多誦先古之書，以亂……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-14_p-4\",\"chapterId\":\"han-fei-zi_ch-14\",\"order\":4,\"canonicalText\":\"處非道之位，被眾口之譖，溺於當世之言，而欲當嚴天子而求安，幾不亦難哉！此夫智士所以至死而不顯於世者也。楚莊王之弟春申君有愛妾曰餘，春申君之正妻子曰甲，餘欲君之棄其妻也，因自傷其身以視君而泣，曰：「得為君之妾，甚幸。雖然，適夫人非所以事君也，適君非所以事夫人也。身故不肖，力不足以適二主，其勢不俱適，與其死夫人所者，不若賜死君前。妾以賜死，若復幸於左右，願君必察之，無為人笑。」君因信妾餘之詐，為棄正妻。餘又欲殺甲而以其子為後，因自裂其親身衣之，以示君而泣，曰：「餘之得幸君之日久矣，甲非弗知也，今乃欲強戲餘，餘與爭之，至裂餘之衣，而此子之不孝，莫大於此矣。」君怒，而殺甲也。故妻以妾餘之詐棄，而子以之死。從是觀之，父之愛子也，猶可以毀而害也。君臣之相與也，非有父子之親也，而群臣之毀言非特一妾之口也，何怪夫賢聖之戮死哉！此商君之所以車裂於秦，而吳起之所以枝解於楚者也。凡人臣者，有罪固不欲誅，無功者皆欲尊顯。而聖人之治國也，賞不加於無功，而誅必行於有罪者也。然則有術數者之為人也，固左右姦臣之所害，非明主弗能聽也。\",\"sentenceIds\":[\"han-fei-zi_ch-14_p-4_s-1\",\"han-fei-zi_ch-14_p-4_s-2\",\"han-fei-zi_ch-14_p-4_s-3\",\"han-fei-zi_ch-14_p-4_s-4\",\"han-fei-zi_ch-14_p-4_s-5\",\"han-fei-zi_ch-14_p-4_s-6\",\"han-fei-zi_ch-14_p-4_s-7\",\"han-fei-zi_ch-14_p-4_s-8\",\"han-fei-zi_ch-14_p-4_s-9\",\"han-fei-zi_ch-14_p-4_s-10\",\"han-fei-zi_ch-14_p-4_s-11\",\"han-fei-zi_ch-14_p-4_s-12\",\"han-fei-zi_ch-14_p-4_s-13\",\"han-fei-zi_ch-14_p-4_s-14\",\"han-fei-zi_ch-14_p-4_s-15\",\"han-fei-zi_ch-14_p-4_s-16\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"處絕不是道的位，被眾口的譖，溺於當世的言，而且欲當嚴天子而且求安，幾不亦難哉！此夫智士所以至死而且不顯於世的人或事物啊。楚莊王的弟春申君主統治者有愛妾說道：餘，春申君主統治者的正妻子說道：甲，餘欲君主統治者的棄他的妻啊，因自傷他的身以視君主統治者而且泣，說道：得為君主統治者的妾，甚幸。雖然，適夫人絕不是所以事君主統治者啊，適君主統治者絕不是所以事夫人啊。身所以不肖，力不足以適二主，他的至高權力威勢不俱適，與他的死夫人所的人或事物，不若賜死君主統治者前。妾以賜死，若復幸於左右，願君主統治者必察的，無為人笑。君主統治者因信妾餘的詐，為棄正妻。餘又欲殺甲而且以他的子為後，因自裂他的親身衣的，以示君主統治者而且泣，說道：餘的得幸君主統治者的日久矣，甲絕不是弗知啊，今乃欲強戲餘，餘與爭的，至裂餘的衣，而且此子的不孝，莫大於此矣。君主統治者怒，而且殺甲啊。所以妻以妾餘的詐棄，而且子以的死。從是觀的，父的愛子啊，猶可以毀而且害啊。君主統治者臣下僚屬的相與啊，絕不是有父子的親啊，而且群臣下僚屬的毀言絕不是特一妾的口啊，何怪夫賢聖的戮死哉！此商君主統治者的所以車裂於秦，而且吳起的所以枝解於楚的人或事物啊。凡人臣下僚屬的人或事物，有罪固不欲誅，無功的人或事物皆欲尊顯。而且聖人的治國啊，賞賜恩惠不加於無功，而且誅必行於有罪的人或事物啊。然則有御臣心術權謀數的人或事物的為人啊，固左右姦臣下僚屬的所害，絕不是明主弗能聽啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈奸劫弒臣〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「處非道之位，被眾口之譖，溺於當世之言，而欲當嚴天子而求安，幾不亦難哉」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「處非道之位，被眾口之譖，溺於當世之言，而欲當嚴天子而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-14_p-5\",\"chapterId\":\"han-fei-zi_ch-14\",\"order\":5,\"canonicalText\":\"世之學術者說人主，不曰「乘威嚴之勢以困姦邪之臣」，而皆曰「仁義惠愛而已矣」。世主美仁義之名而不察其實，是以大者國亡身死，小者地削主卑。何以明之？夫施與貧困者，此世之所謂仁義；哀憐百姓不忍誅罰者，此世之所謂惠愛也。夫有施與貧困，則無功者得賞；不忍誅罰，則暴亂者不止。國有無功得賞者，則民不外務當敵斬首，內不急力田疾作，皆欲行貨財、事富貴、為私善、立名譽以取尊官厚俸。故姦私之臣愈眾，而暴亂之徒愈勝，不亡何待？夫嚴刑者，民之所畏也；重罰者，民之所惡也。故聖人陳其所畏以禁其邪，設其所惡以防其姦。是以國安而暴亂不起。吾以是明仁義愛惠之不足用，而嚴刑重罰之可以治國也。無捶策之威，銜橛之備，雖造父不能以服馬。無規矩之法，繩墨之端，雖王爾不能以成方圓。無威嚴之勢，賞罰之法，雖堯、舜不能以為治。今世主皆輕釋重罰、嚴誅，行愛惠，而欲霸王之功，亦不可幾也。故善為主者，明賞設利以勸之，使民以功賞，而不以仁義賜；嚴刑重罰以禁之，使民以罪誅而不以愛惠免。是以無功者不望，而有罪者不幸矣。託於犀車良馬之上，則可以陸犯阪阻之患；乘舟之安，持楫之利，則可以水絕江河之難；操法術之數，行重罰嚴誅，則可以致霸王之功。治國之有法術賞罰，猶若陸行之有犀車良馬也，水行之有輕舟便楫也，乘之者遂得其成。伊尹得之湯以王，管仲得之齊以霸，商君得之秦以強。此三人者，皆明於霸王之術，察於治強之數，而不以牽於世俗之言；適當世明主之意，則有直任布衣之士，立為卿相之處；處位治國，則有尊主廣地之實；此之謂足貴之臣。湯得伊尹，以百里之地立為天子；桓公得管仲，立為五霸主，九合諸侯，一匡天下；孝公得商君，地以廣，兵以強。故有忠臣者，外無敵國之患，內無亂臣之憂，長安於天下，而名垂後世，所謂忠臣也。若夫豫讓為智伯臣也，上不能說人主使之明法術、度數之理，以避禍難之患，下不能領御其眾，以安其國；及襄子之殺智伯也，豫讓乃自黔劓，敗其形容，以為智伯報襄子之仇；是雖有殘刑殺身以為人主之名，而實無益於智伯若秋毫之末。此吾之所下也，而世主以為忠而高之。古有伯夷、叔齊者，武王讓以天下而弗受，二人餓死首陽之陵；若此臣者，不畏重誅，不利重賞，不可以罰禁也，不可以賞使也。此之謂無益之臣也，吾所少而去也，而世主之所多而求也。\",\"sentenceIds\":[\"han-fei-zi_ch-14_p-5_s-1\",\"han-fei-zi_ch-14_p-5_s-2\",\"han-fei-zi_ch-14_p-5_s-3\",\"han-fei-zi_ch-14_p-5_s-4\",\"han-fei-zi_ch-14_p-5_s-5\",\"han-fei-zi_ch-14_p-5_s-6\",\"han-fei-zi_ch-14_p-5_s-7\",\"han-fei-zi_ch-14_p-5_s-8\",\"han-fei-zi_ch-14_p-5_s-9\",\"han-fei-zi_ch-14_p-5_s-10\",\"han-fei-zi_ch-14_p-5_s-11\",\"han-fei-zi_ch-14_p-5_s-12\",\"han-fei-zi_ch-14_p-5_s-13\",\"han-fei-zi_ch-14_p-5_s-14\",\"han-fei-zi_ch-14_p-5_s-15\",\"han-fei-zi_ch-14_p-5_s-16\",\"han-fei-zi_ch-14_p-5_s-17\",\"han-fei-zi_ch-14_p-5_s-18\",\"han-fei-zi_ch-14_p-5_s-19\",\"han-fei-zi_ch-14_p-5_s-20\",\"han-fei-zi_ch-14_p-5_s-21\",\"han-fei-zi_ch-14_p-5_s-22\",\"han-fei-zi_ch-14_p-5_s-23\",\"han-fei-zi_ch-14_p-5_s-24\",\"han-fei-zi_ch-14_p-5_s-25\",\"han-fei-zi_ch-14_p-5_s-26\",\"han-fei-zi_ch-14_p-5_s-27\",\"han-fei-zi_ch-14_p-5_s-28\",\"han-fei-zi_ch-14_p-5_s-29\",\"han-fei-zi_ch-14_p-5_s-30\",\"han-fei-zi_ch-14_p-5_s-31\",\"han-fei-zi_ch-14_p-5_s-32\",\"han-fei-zi_ch-14_p-5_s-33\",\"han-fei-zi_ch-14_p-5_s-34\",\"han-fei-zi_ch-14_p-5_s-35\",\"han-fei-zi_ch-14_p-5_s-36\",\"han-fei-zi_ch-14_p-5_s-37\",\"han-fei-zi_ch-14_p-5_s-38\",\"han-fei-zi_ch-14_p-5_s-39\",\"han-fei-zi_ch-14_p-5_s-40\",\"han-fei-zi_ch-14_p-5_s-41\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世的學御臣心術權謀的人或事物說人主，不說道：乘威嚴的至高權力威勢以困姦邪的臣下僚屬，而且皆說道：仁義惠愛而且已矣。世主美仁義的名而且不察他的實，是以大的人或事物國亡身死，小的人或事物地削主卑。何以明的？夫施與貧困的人或事物，此世的所謂仁義；哀憐百姓不忍誅刑罰制裁的人或事物，此世的所謂惠愛啊。夫有施與貧困，則無功的人或事物得賞賜恩惠；不忍誅刑罰制裁，則暴亂的人或事物不止。國有無功得賞賜恩惠的人或事物，則民不外務當敵斬首，內不急力田疾作，皆欲行貨財、事富貴、為私善、立名譽以取尊官厚俸。所以姦私的臣下僚屬愈眾，而且暴亂的徒愈勝，不亡何待？夫嚴刑的人或事物，民的所畏啊；重刑罰制裁的人或事物，民的所惡啊。所以聖人陳他的所畏以禁他的邪，設他的所惡以防他的姦。是以國安而且暴亂不起。吾以是明仁義愛惠的不足用，而且嚴刑重刑罰制裁的可以治國啊。無捶策的威，銜橛的備，雖造父不能以服馬。無規矩的國家法度法規，繩墨的端，雖王爾不能以成方圓。無威嚴的至高權力威勢，賞賜恩惠刑罰制裁的國家法度法規，雖堯、舜不能以為治。今世主皆輕釋重刑罰制裁、嚴誅，行愛惠，而且欲霸王的功，亦不可幾啊。所以善為主的人或事物，明賞賜恩惠設利以勸的，使民以功賞賜恩惠，而且不以仁義賜；嚴刑重刑罰制裁以禁的，使民以罪誅而且不以愛惠免。是以無功的人或事物不望，而且有罪的人或事物不幸矣。託於犀車良馬的上，則可以陸犯阪阻的患；乘舟的安，持楫的利，則可以水絕江河的難；操國家法度法規御臣心術權謀的數，行重刑罰制裁嚴誅，則可以致霸王的功。治國的有國家法度法規御臣心術權謀賞賜恩惠刑罰制裁，猶若陸行的有犀車良馬啊，水行的有輕舟便楫啊，乘的的人或事物遂得他的成。伊尹得的湯以王，管仲得的齊以霸，商君主統治者得的秦以強。此三人的人或事物，皆明於霸王的御臣心術權謀，察於治強的數，而且不以牽於世俗的言；適當世明主的意，則有直任布衣的士，立為卿相的處；處位治國，則有尊主廣地的實；此的謂足貴的臣下僚屬。湯得伊尹，以百里的地立為天子；桓公得管仲，立為五霸主，九合諸侯，一匡天下；孝公得商君主統治者，地以廣，兵以強。所以有忠臣下僚屬的人或事物，外無敵國的患，內無亂臣下僚屬的憂，長安於天下，而且名垂後世，所謂忠臣下僚屬啊。至於談到那豫讓為智伯臣下僚屬啊，上不能說人主使的明國家法度法規御臣心術權謀、度數的理，以避禍難的患，下不能領御他的眾，以安他的國；及襄子的殺智伯啊，豫讓乃自黔劓，敗他的形容，以為智伯報襄子的仇；是雖有殘刑殺身以為人主的名，而且實無益於智伯若秋毫的末。此吾的所下啊，而且世主以為忠而且高的。古有伯夷、叔齊的人或事物，武王讓以天下而且弗受，二人餓死首陽的陵；若此臣下僚屬的人或事物，不畏重誅，不利重賞賜恩惠，不可以刑罰制裁禁啊，不可以賞賜恩惠使啊。此的謂無益的臣下僚屬啊，吾所少而且去啊，而且世主的所多而且求啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈奸劫弒臣〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「世之學術者說人主，不曰「乘威嚴之勢以困姦邪之臣」，而皆曰「仁義惠愛而已矣」」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「世之學術者說人主，不曰「乘威嚴之勢以困姦邪之臣」，而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-14_p-6\",\"chapterId\":\"han-fei-zi_ch-14\",\"order\":6,\"canonicalText\":\"諺曰：「厲憐王。」此不恭之言也。雖然，古無虛諺，不可不察也。此謂劫殺死亡之主言也。人主無法術以御其臣，雖長年而美材，大臣猶將得勢擅事主斷，而各為其私急。而恐父兄豪傑之士，借人主之力，以禁誅於己也，故弒賢長而立幼弱，廢正的而立不義。故春秋記之曰：「楚王子圍將聘於鄭，未出境，聞王病而反，因入問病，以其冠纓絞王而殺之，遂自立也。齊崔杼，其妻美，而莊公通之，數如崔氏之室，及公往，崔子之徒賈舉率崔子之徒而攻公，公入室，請與之分國，崔子不許，公請自刃於廟，崔子又不聽，公乃走踰於北牆，賈舉射公，中其股，公墜，崔子之徒以戈斫公而死之，而立其弟景公。」近之所見：李兌之用趙也，餓主父百日而死；卓齒之用齊也，擢湣王之筋，懸之廟梁，宿昔而死。故厲雖癰腫疕瘍，上比於春秋，未至於絞頸射股也；下比於近世，未至餓死擢筋也。故劫殺死亡之君，此其心之憂懼、形之苦痛也，必甚於厲矣。由此觀之，雖「厲憐王」可也。\",\"sentenceIds\":[\"han-fei-zi_ch-14_p-6_s-1\",\"han-fei-zi_ch-14_p-6_s-2\",\"han-fei-zi_ch-14_p-6_s-3\",\"han-fei-zi_ch-14_p-6_s-4\",\"han-fei-zi_ch-14_p-6_s-5\",\"han-fei-zi_ch-14_p-6_s-6\",\"han-fei-zi_ch-14_p-6_s-7\",\"han-fei-zi_ch-14_p-6_s-8\",\"han-fei-zi_ch-14_p-6_s-9\",\"han-fei-zi_ch-14_p-6_s-10\",\"han-fei-zi_ch-14_p-6_s-11\",\"han-fei-zi_ch-14_p-6_s-12\",\"han-fei-zi_ch-14_p-6_s-13\",\"han-fei-zi_ch-14_p-6_s-14\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"諺說道：厲憐王。此不恭的言啊。雖然，古無虛諺，不可不察啊。此謂劫殺死亡的主言啊。人主無國家法度法規御臣心術權謀以御他的臣下僚屬，雖長年而且美材，大臣下僚屬猶將得至高權力威勢擅事主斷，而且各為他的私急。而且恐父兄豪傑的士，借人主的力，以禁誅於己啊，所以弒賢長而且立幼弱，廢正的而且立不義。所以春秋記的說道：楚王子圍將聘於鄭，未出境，聞王病而且反，因入問病，以他的冠纓絞王而且殺的，遂自立啊。齊崔杼，他的妻美，而且莊公通的，數如崔氏的室，及公往，崔子的徒賈舉率崔子的徒而且攻公，公入室，請與的分國，崔子不許，公請自刃於廟，崔子又不聽，公乃走踰於北牆，賈舉射公，中他的股，公墜，崔子的徒以戈斫公而且死的，而且立他的弟景公。近的所見：李兌的用趙啊，餓主父百日而且死；卓齒的用齊啊，擢湣王的筋，懸的廟梁，宿昔而且死。所以厲雖癰腫疕瘍，上比於春秋，未至於絞頸射股啊；下比於近世，未至餓死擢筋啊。所以劫殺死亡的君主統治者，此他的心的憂懼、形的苦痛啊，必甚於厲矣。由此觀的，雖厲憐王可啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈奸劫弒臣〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「諺曰：「厲憐王」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「諺曰：「厲憐王。」此不恭之言也。雖然，古無虛諺，不可……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"han-fei-zi_ch-14_p-1_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":1,\"canonicalText\":\"凡姦臣皆欲順人主之心以取親幸之勢者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":2,\"canonicalText\":\"是以主有所善，臣從而譽之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":3,\"canonicalText\":\"主有所憎，臣因而毀之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":4,\"canonicalText\":\"凡人之大體，取捨同者則相是也，取捨異者則相非也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":5,\"canonicalText\":\"今人臣之所譽者，人主之所是也，此之謂同取。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":6,\"canonicalText\":\"人臣之所毀者，人主之所非也，此之謂同舍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":7,\"canonicalText\":\"夫取捨合而相與逆者，未嘗聞也，此人臣之所以取信幸之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":8,\"canonicalText\":\"夫姦臣得乘信幸之勢以毀譽進退群臣者，人主非有術數以御之也，非參驗以審之也，必將以曩之合己信今之言，此倖臣之所以得欺主成私者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":9,\"canonicalText\":\"故主必欺於上，而臣必重於下矣，此之謂擅主之臣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":10,\"canonicalText\":\"國有擅主之臣，則羣下不得盡其智力以陳其忠，百官之吏不得奉法以致其功矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":11,\"canonicalText\":\"何以明之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":12,\"canonicalText\":\"夫安利者就之，危害者去之，此人之情也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":13,\"canonicalText\":\"今為臣盡力以致功，竭智以陳忠者，其身困而家貧，父子罹其害；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":14,\"canonicalText\":\"為姦利以弊人主，行財貨以事貴重之臣者，身尊家富，父子被其澤；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":15,\"canonicalText\":\"人焉能去安利之道而就危害之處哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":16,\"canonicalText\":\"治國若此其過也，而上欲下之無姦，吏之奉法，其不可得亦明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":17,\"canonicalText\":\"故左右知貞信之不可以得安利也，必曰：「我以忠信事上積功勞而求安，是猶盲而欲知黑白之情，必不幾矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":18,\"canonicalText\":\"若以道化行正理不趨富貴事上而求安，是猶聾而欲審清濁之聲也，愈不幾矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":19,\"canonicalText\":\"二者不可以得安，我安能無相比周、蔽主上、為姦私以適重人哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":20,\"canonicalText\":\"」此必不顧人主之義矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":21,\"canonicalText\":\"其百官之吏，亦知方正之不可以得安也，必曰：「我以清廉事上而求安，若無規矩而欲為方圓也，必不幾矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-22\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":22,\"canonicalText\":\"若以守法不朋黨治官而求安，是猶以足搔頂也，愈不幾也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-23\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":23,\"canonicalText\":\"二者不可以得安，能無廢法行私以適重人哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-24\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":24,\"canonicalText\":\"」此必不顧君上之法矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-25\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":25,\"canonicalText\":\"故以私為重人者眾，而以法事君者少矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-1_s-26\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-1\",\"order\":26,\"canonicalText\":\"是以主孤於上而臣成黨於下，此田成之所以弒簡公者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":1,\"canonicalText\":\"夫有術者之為人臣也，得效度數之言，上明主法，下困姦臣，以尊主安國者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":2,\"canonicalText\":\"是以度數之言得效於前，則賞罰必用於後矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":3,\"canonicalText\":\"人主誠明於聖人之術，而不苟於世俗之言，循名實而定是非，因參驗而審言辭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":4,\"canonicalText\":\"是以左右近習之臣，知偽詐之不可以得安也，必曰：「我不去姦私之行盡力竭智以事主，而乃以相與比周妄毀譽以求安，是猶負千鈞之重，陷於不測之淵而求生也，必不幾矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":5,\"canonicalText\":\"」百官之吏，亦知為姦利之不可以得安也，必曰：「我不以清廉方正奉法，乃以貪污之心枉法以取私利，是猶上高陵之顛，墮峻谿之下而求生，必不幾矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":6,\"canonicalText\":\"」安危之道若此其明也，左右安能以虛言惑主，而百官安敢以貪漁下？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":7,\"canonicalText\":\"是以臣得陳其忠而不弊，下得守其職而不怨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":8,\"canonicalText\":\"此管仲之所以治齊，而商君之所以強秦也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":9,\"canonicalText\":\"從是觀之，則聖人之治國也，固有使人不得不愛我之道，而不恃人之以愛為我也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":10,\"canonicalText\":\"恃人之以愛為我者危矣，恃吾不可不為者安矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":11,\"canonicalText\":\"夫君臣非有骨肉之親，正直之道可以得利，則臣盡力以事主；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":12,\"canonicalText\":\"正直之道不可以得安，則臣行私以幹上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":13,\"canonicalText\":\"明主知之，故設利害之道以示天下而已矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":14,\"canonicalText\":\"夫是以人主雖不口教百官，不目索姦邪，而國已治矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":15,\"canonicalText\":\"人主者，非目若離婁乃為明也，非耳若師曠乃為聰也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":16,\"canonicalText\":\"目必，不任其數，而待目以為明，所見者少矣，非不弊之術也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":17,\"canonicalText\":\"耳必，不因其勢，而待耳以為聰，所聞者寡矣，非不欺之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":18,\"canonicalText\":\"明主者，使天下不得不為己視，天下不得不為己聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":19,\"canonicalText\":\"故身在深宮之中而明照四海之內，而天下弗能蔽、弗能欺者何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":20,\"canonicalText\":\"闇亂之道廢，而聰明之勢興也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":21,\"canonicalText\":\"故善任勢者國安，不知因其勢者國危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-22\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":22,\"canonicalText\":\"古秦之俗，君臣廢法而服私，是以國亂兵弱而主卑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-23\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":23,\"canonicalText\":\"商君說秦孝公以變法易俗而明公道，賞告姦，困末作而利本事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-24\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":24,\"canonicalText\":\"當此之時，秦民習故俗之有罪可以得免、無功可以得尊顯也，故輕犯新法。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-25\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":25,\"canonicalText\":\"於是犯之者其誅重而必，告之者其賞厚而信，故姦莫不得而被刑者眾，民疾怨而眾過日聞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-26\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":26,\"canonicalText\":\"孝公不聽，遂行商君之法，民後知有罪之必誅，而私姦者眾也，故民莫犯，其刑無所加。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-27\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":27,\"canonicalText\":\"是以國治而兵強，地廣而主尊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-28\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":28,\"canonicalText\":\"此其所以然者，匿罪之罰重，而告姦之賞厚也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-29\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":29,\"canonicalText\":\"此亦使天下必為己視聽之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-2_s-30\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-2\",\"order\":30,\"canonicalText\":\"至治之法術已明矣，而世學者弗知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":1,\"canonicalText\":\"且夫世之愚學，皆不知治亂之情，讘䛟多誦先古之書，以亂當世之治；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":2,\"canonicalText\":\"智慮不足以避阱井之陷，又妄非有術之士。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":3,\"canonicalText\":\"聽其言者危，用其計者亂，此亦愚之至大，而患之至甚者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":4,\"canonicalText\":\"俱與有術之士，有談說之名，而實相去千萬也，此夫名同而實有異者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":5,\"canonicalText\":\"夫世愚學之人比有術之士也，猶螘垤之比大陵也，其相去遠矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":6,\"canonicalText\":\"而聖人者，審於是非之實，察於治亂之情也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":7,\"canonicalText\":\"故其治國也，正明法，陳嚴刑，將以救羣生之亂，去天下之禍，使強不陵弱，眾不暴寡，耆老得遂，幼孤得長，邊境不侵，君臣相親，父子相保，而無死亡係虜之患，此亦功之至厚者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":8,\"canonicalText\":\"愚人不知，顧以為暴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":9,\"canonicalText\":\"愚者固欲治而惡其所以治，皆惡危而喜其所以危者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":10,\"canonicalText\":\"何以知之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":11,\"canonicalText\":\"夫嚴刑重罰者，民之所惡也，而國之所以治也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":12,\"canonicalText\":\"哀憐百姓、輕刑罰者，民之所喜，而國之所以危也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":13,\"canonicalText\":\"聖人為法國者，必逆於世，而順於道德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":14,\"canonicalText\":\"知之者，同於義而異於俗；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":15,\"canonicalText\":\"弗知之者，異於義而同於俗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-3_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-3\",\"order\":16,\"canonicalText\":\"天下知之者少，則義非矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":1,\"canonicalText\":\"處非道之位，被眾口之譖，溺於當世之言，而欲當嚴天子而求安，幾不亦難哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":2,\"canonicalText\":\"此夫智士所以至死而不顯於世者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":3,\"canonicalText\":\"楚莊王之弟春申君有愛妾曰餘，春申君之正妻子曰甲，餘欲君之棄其妻也，因自傷其身以視君而泣，曰：「得為君之妾，甚幸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":4,\"canonicalText\":\"雖然，適夫人非所以事君也，適君非所以事夫人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":5,\"canonicalText\":\"身故不肖，力不足以適二主，其勢不俱適，與其死夫人所者，不若賜死君前。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":6,\"canonicalText\":\"妾以賜死，若復幸於左右，願君必察之，無為人笑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":7,\"canonicalText\":\"」君因信妾餘之詐，為棄正妻。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":8,\"canonicalText\":\"餘又欲殺甲而以其子為後，因自裂其親身衣之，以示君而泣，曰：「餘之得幸君之日久矣，甲非弗知也，今乃欲強戲餘，餘與爭之，至裂餘之衣，而此子之不孝，莫大於此矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":9,\"canonicalText\":\"」君怒，而殺甲也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":10,\"canonicalText\":\"故妻以妾餘之詐棄，而子以之死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":11,\"canonicalText\":\"從是觀之，父之愛子也，猶可以毀而害也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":12,\"canonicalText\":\"君臣之相與也，非有父子之親也，而群臣之毀言非特一妾之口也，何怪夫賢聖之戮死哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":13,\"canonicalText\":\"此商君之所以車裂於秦，而吳起之所以枝解於楚者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":14,\"canonicalText\":\"凡人臣者，有罪固不欲誅，無功者皆欲尊顯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":15,\"canonicalText\":\"而聖人之治國也，賞不加於無功，而誅必行於有罪者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-4_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-4\",\"order\":16,\"canonicalText\":\"然則有術數者之為人也，固左右姦臣之所害，非明主弗能聽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":1,\"canonicalText\":\"世之學術者說人主，不曰「乘威嚴之勢以困姦邪之臣」，而皆曰「仁義惠愛而已矣」。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":2,\"canonicalText\":\"世主美仁義之名而不察其實，是以大者國亡身死，小者地削主卑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":3,\"canonicalText\":\"何以明之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":4,\"canonicalText\":\"夫施與貧困者，此世之所謂仁義；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":5,\"canonicalText\":\"哀憐百姓不忍誅罰者，此世之所謂惠愛也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":6,\"canonicalText\":\"夫有施與貧困，則無功者得賞；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":7,\"canonicalText\":\"不忍誅罰，則暴亂者不止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":8,\"canonicalText\":\"國有無功得賞者，則民不外務當敵斬首，內不急力田疾作，皆欲行貨財、事富貴、為私善、立名譽以取尊官厚俸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":9,\"canonicalText\":\"故姦私之臣愈眾，而暴亂之徒愈勝，不亡何待？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":10,\"canonicalText\":\"夫嚴刑者，民之所畏也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":11,\"canonicalText\":\"重罰者，民之所惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":12,\"canonicalText\":\"故聖人陳其所畏以禁其邪，設其所惡以防其姦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":13,\"canonicalText\":\"是以國安而暴亂不起。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":14,\"canonicalText\":\"吾以是明仁義愛惠之不足用，而嚴刑重罰之可以治國也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":15,\"canonicalText\":\"無捶策之威，銜橛之備，雖造父不能以服馬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":16,\"canonicalText\":\"無規矩之法，繩墨之端，雖王爾不能以成方圓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":17,\"canonicalText\":\"無威嚴之勢，賞罰之法，雖堯、舜不能以為治。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":18,\"canonicalText\":\"今世主皆輕釋重罰、嚴誅，行愛惠，而欲霸王之功，亦不可幾也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":19,\"canonicalText\":\"故善為主者，明賞設利以勸之，使民以功賞，而不以仁義賜；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":20,\"canonicalText\":\"嚴刑重罰以禁之，使民以罪誅而不以愛惠免。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":21,\"canonicalText\":\"是以無功者不望，而有罪者不幸矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-22\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":22,\"canonicalText\":\"託於犀車良馬之上，則可以陸犯阪阻之患；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-23\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":23,\"canonicalText\":\"乘舟之安，持楫之利，則可以水絕江河之難；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-24\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":24,\"canonicalText\":\"操法術之數，行重罰嚴誅，則可以致霸王之功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-25\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":25,\"canonicalText\":\"治國之有法術賞罰，猶若陸行之有犀車良馬也，水行之有輕舟便楫也，乘之者遂得其成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-26\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":26,\"canonicalText\":\"伊尹得之湯以王，管仲得之齊以霸，商君得之秦以強。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-27\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":27,\"canonicalText\":\"此三人者，皆明於霸王之術，察於治強之數，而不以牽於世俗之言；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-28\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":28,\"canonicalText\":\"適當世明主之意，則有直任布衣之士，立為卿相之處；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-29\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":29,\"canonicalText\":\"處位治國，則有尊主廣地之實；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-30\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":30,\"canonicalText\":\"此之謂足貴之臣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-31\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":31,\"canonicalText\":\"湯得伊尹，以百里之地立為天子；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-32\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":32,\"canonicalText\":\"桓公得管仲，立為五霸主，九合諸侯，一匡天下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-33\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":33,\"canonicalText\":\"孝公得商君，地以廣，兵以強。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-34\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":34,\"canonicalText\":\"故有忠臣者，外無敵國之患，內無亂臣之憂，長安於天下，而名垂後世，所謂忠臣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-35\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":35,\"canonicalText\":\"若夫豫讓為智伯臣也，上不能說人主使之明法術、度數之理，以避禍難之患，下不能領御其眾，以安其國；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-36\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":36,\"canonicalText\":\"及襄子之殺智伯也，豫讓乃自黔劓，敗其形容，以為智伯報襄子之仇；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-37\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":37,\"canonicalText\":\"是雖有殘刑殺身以為人主之名，而實無益於智伯若秋毫之末。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-38\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":38,\"canonicalText\":\"此吾之所下也，而世主以為忠而高之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-39\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":39,\"canonicalText\":\"古有伯夷、叔齊者，武王讓以天下而弗受，二人餓死首陽之陵；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-40\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":40,\"canonicalText\":\"若此臣者，不畏重誅，不利重賞，不可以罰禁也，不可以賞使也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-5_s-41\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-5\",\"order\":41,\"canonicalText\":\"此之謂無益之臣也，吾所少而去也，而世主之所多而求也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":1,\"canonicalText\":\"諺曰：「厲憐王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":2,\"canonicalText\":\"」此不恭之言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":3,\"canonicalText\":\"雖然，古無虛諺，不可不察也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":4,\"canonicalText\":\"此謂劫殺死亡之主言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":5,\"canonicalText\":\"人主無法術以御其臣，雖長年而美材，大臣猶將得勢擅事主斷，而各為其私急。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":6,\"canonicalText\":\"而恐父兄豪傑之士，借人主之力，以禁誅於己也，故弒賢長而立幼弱，廢正的而立不義。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":7,\"canonicalText\":\"故春秋記之曰：「楚王子圍將聘於鄭，未出境，聞王病而反，因入問病，以其冠纓絞王而殺之，遂自立也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":8,\"canonicalText\":\"齊崔杼，其妻美，而莊公通之，數如崔氏之室，及公往，崔子之徒賈舉率崔子之徒而攻公，公入室，請與之分國，崔子不許，公請自刃於廟，崔子又不聽，公乃走踰於北牆，賈舉射公，中其股，公墜，崔子之徒以戈斫公而死之，而立其弟景公。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":9,\"canonicalText\":\"」近之所見：李兌之用趙也，餓主父百日而死；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":10,\"canonicalText\":\"卓齒之用齊也，擢湣王之筋，懸之廟梁，宿昔而死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":11,\"canonicalText\":\"故厲雖癰腫疕瘍，上比於春秋，未至於絞頸射股也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":12,\"canonicalText\":\"下比於近世，未至餓死擢筋也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":13,\"canonicalText\":\"故劫殺死亡之君，此其心之憂懼、形之苦痛也，必甚於厲矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-14_p-6_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-14\",\"passageId\":\"han-fei-zi_ch-14_p-6\",\"order\":14,\"canonicalText\":\"由此觀之，雖「厲憐王」可也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
